def authenticate_user(user_token, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _ulid_like(prefix, s):
        return isinstance(s, str) and s.startswith(prefix) and len(s) >= len(prefix) + 8

    def _hash_token(raw):
        # Vendor store keeps token_hash, and rule says "system MUST hash it and look up"
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    # minimal request log store (created on demand)
    def _log_call(endpoint, credential, status, latency_ms, user_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "aik_log_" + hashlib.sha1(f"{time.time_ns()}".encode()).hexdigest()[:20],
            "endpoint": endpoint,
            "credential": credential,
            "user_id": user_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate input
    if user_token is None or not isinstance(user_token, str):
        latency = int((time.time() - t0) * 1000)
        _log_call("authenticate_user", None, "error:VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "user_token must be a non-empty string")
    user_token = user_token.strip()
    if not user_token:
        latency = int((time.time() - t0) * 1000)
        _log_call("authenticate_user", None, "error:VALIDATION_ERROR", latency)
        return _err("VALIDATION_ERROR", "user_token must be a non-empty string")

    users = _load("users.json")
    auth_tokens = _load("auth_tokens.json")

    if not isinstance(users, list) or not isinstance(auth_tokens, list):
        latency = int((time.time() - t0) * 1000)
        _log_call("authenticate_user", user_token[:16], "error:CONFLICT", latency)
        return _err("CONFLICT", "Datastore is not in expected format")

    now = _now()

    def _find_user(uid):
        for u in users:
            if isinstance(u, dict) and u.get("id") == uid:
                return u
        return None

    resolved_user = None
    used_credential = None
    used_token_row = None

    # If token looks like user id, accept it
    if _ulid_like("aik_usr_", user_token):
        u = _find_user(user_token)
        if u is None:
            latency = int((time.time() - t0) * 1000)
            _log_call("authenticate_user", "user_id", "error:NOT_FOUND", latency)
            return _err("NOT_FOUND", "User not found")
        resolved_user = u
        used_credential = u.get("id")
    else:
        # raw token -> hash -> lookup in auth_tokens where active and not expired
        h = _hash_token(user_token)
        for tok in auth_tokens:
            if not isinstance(tok, dict):
                continue
            if tok.get("token_hash") != h:
                continue
            if tok.get("status") != "active":
                continue
            exp = _parse_dt(tok.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            u = _find_user(tok.get("user_id"))
            if u is None:
                continue
            resolved_user = u
            used_token_row = tok
            used_credential = tok.get("id") or "auth_token"
            break

        if resolved_user is None:
            latency = int((time.time() - t0) * 1000)
            _log_call("authenticate_user", "raw_token", "error:UNAUTHORIZED", latency)
            return _err("UNAUTHORIZED", "Invalid or expired token")

    # user status checks
    if resolved_user.get("status") in ("suspended", "deleted"):
        latency = int((time.time() - t0) * 1000)
        _log_call("authenticate_user", used_credential, "error:UNAUTHORIZED", latency, user_id=resolved_user.get("id"))
        return _err("UNAUTHORIZED", f"User is {resolved_user.get('status')}")

    # update last_used_at for token auth (best-effort; must not fabricate row)
    if used_token_row is not None:
        # Find and update in list to persist
        tok_id = used_token_row.get("id")
        for tok in auth_tokens:
            if isinstance(tok, dict) and tok.get("id") == tok_id:
                tok["last_used_at"] = _iso(now)
                tok["updated_at"] = _iso(now)
                break
        _save("auth_tokens.json", auth_tokens)

    latency = int((time.time() - t0) * 1000)
    _log_call("authenticate_user", used_credential, "ok", latency, user_id=resolved_user.get("id"))

    # Return auth context (caller holds it; other tools will also accept ambient auth via _extra)
    return {
        "user": {
            "id": resolved_user.get("id"),
            "display_name": resolved_user.get("display_name"),
            "email": resolved_user.get("email"),
            "status": resolved_user.get("status"),
            "created_at": resolved_user.get("created_at"),
            "updated_at": resolved_user.get("updated_at"),
        },
        "credential": {
            "type": "user_id" if _ulid_like("aik_usr_", user_token) else "auth_token",
            "value": used_credential,
        },
        "authenticated_at": _iso(now),
    }

def search_user_prompts(query, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        try:
            if t.endswith("Z"):
                t = t[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return logs
        return []

    def _log(endpoint, credential, status, latency_ms, user_id=None, meta=None):
        logs = _ensure_request_logs()
        row = {
            "id": "aik_log_" + hashlib.sha1(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "credential": credential,
            "user_id": user_id,
            "status": status,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) else None,
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(user_id, endpoint, limit=60, window_sec=60):
        # No user_id -> cannot rate limit precisely; allow but still log.
        if not user_id:
            return True, None
        logs = _ensure_request_logs()
        now = _now()
        cutoff = now - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("user_id") != user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, {"limit": limit, "window_sec": window_sec}
        return True, None

    def _get_ambient_credential():
        # Explicit in _extra preferred; else env.
        for k in ("user_token", "auth_token", "token", "authorization"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                return v.strip()
        v = os.environ.get("AIK_USER_TOKEN") or os.environ.get("USER_TOKEN") or os.environ.get("AUTH_TOKEN")
        if isinstance(v, str) and v.strip():
            return v.strip()
        uid = os.environ.get("AIK_USER_ID") or os.environ.get("USER_ID")
        if isinstance(uid, str) and uid.strip():
            return uid.strip()
        return None

    def _hash_token(raw):
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _resolve_user():
        users = _load("users.json")
        tokens = _load("auth_tokens.json")
        now = _now()

        provided = _get_ambient_credential()

        def _user_active(u):
            return isinstance(u, dict) and u.get("status") == "active"

        # If provided looks like a user id.
        if isinstance(provided, str) and provided.startswith("aik_usr_"):
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == provided), None)
            if not u or not _user_active(u):
                return None, None
            return u, {"id": None, "kind": "user_id", "value": provided}

        # If provided looks like a token record id, accept by id (client-visible id).
        if isinstance(provided, str) and provided.startswith("aik_tok_"):
            t = next((x for x in tokens if isinstance(x, dict) and x.get("id") == provided), None)
            if not t or t.get("status") != "active":
                return None, None
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                return None, None
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
            if not u or not _user_active(u):
                return None, None
            return u, {"id": t.get("id"), "kind": "token_id", "value": provided}

        # If provided is a raw token, hash it and match token_hash
        if isinstance(provided, str) and provided.strip():
            h = _hash_token(provided.strip())
            t = next((x for x in tokens if isinstance(x, dict) and x.get("token_hash") == h and x.get("status") == "active"), None)
            if t:
                exp = _parse_dt(t.get("expires_at"))
                if exp is None or exp > now:
                    u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
                    if u and _user_active(u):
                        return u, {"id": t.get("id"), "kind": "token_hash", "value": None}

        # Ambient auth: choose any active token with active user (must not fail a well-formed call)
        candidates = []
        for t in tokens:
            if not isinstance(t, dict): 
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                continue
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
            if not u or not _user_active(u):
                continue
            lu = _parse_dt(t.get("last_used_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            ca = _parse_dt(t.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            candidates.append((lu, ca, t, u))
        if not candidates:
            return None, None
        candidates.sort(reverse=True)
        _, _, t, u = candidates[0]
        return u, {"id": t.get("id"), "kind": "ambient", "value": None}

    start = time.time()

    # Validate input first
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    if len(q) < 1:
        return _err("VALIDATION_ERROR", "query must not be empty")
    if len(q) > 256:
        return _err("VALIDATION_ERROR", "query too long (max 256)")

    user, cred = _resolve_user()
    if not user:
        latency = int((time.time() - start) * 1000)
        _log("search_user_prompts", None, "UNAUTHORIZED", latency, user_id=None, meta={"query_len": len(q)})
        return _err("UNAUTHORIZED", "Not authenticated")

    ok, info = _rate_limit_check(user.get("id"), "search_user_prompts", limit=60, window_sec=60)
    if not ok:
        latency = int((time.time() - start) * 1000)
        _log("search_user_prompts", cred.get("id") if cred else None, "RATE_LIMIT", latency, user_id=user.get("id"), meta=info)
        return _err("RATE_LIMIT", "Too many requests", **(info or {}))

    prompts = _load("prompts.json")
    shares = _load("prompt_shares.json")

    uid = user.get("id")

    # Build accessible prompt_id set for shared (active shares)
    shared_ids = set()
    for s in shares:
        if not isinstance(s, dict):
            continue
        if s.get("status") != "active":
            continue
        if s.get("shared_with_user_id") != uid:
            continue
        pid = s.get("prompt_id")
        if isinstance(pid, str) and pid:
            shared_ids.add(pid)

    def _match_text(p, needle):
        st = p.get("search_text")
        if not isinstance(st, str) or not st:
            # Fallback: build from name/description/template snippet
            name = p.get("name") if isinstance(p.get("name"), str) else ""
            desc = p.get("description") if isinstance(p.get("description"), str) else ""
            tpl = p.get("template") if isinstance(p.get("template"), str) else ""
            st = (name + " " + desc + " " + tpl[:5000]).lower()
        return needle in st.lower()

    needle = q.lower()
    results = []
    for p in prompts:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        pid = p.get("id")
        if not isinstance(pid, str):
            continue

        accessible = False
        if p.get("owner_user_id") == uid:
            accessible = True
        elif p.get("visibility") == "public":
            accessible = True
        elif pid in shared_ids:
            accessible = True

        if not accessible:
            continue

        if _match_text(p, needle):
            results.append(p)

    # Deterministic sort: owned first, then shared, then public, then name, then id
    def _scope_rank(p):
        if p.get("owner_user_id") == uid:
            return 0
        if isinstance(p.get("id"), str) and p.get("id") in shared_ids:
            return 1
        if p.get("visibility") == "public":
            return 2
        return 3

    results.sort(key=lambda p: (_scope_rank(p), (p.get("name") or ""), (p.get("id") or "")))

    # Enforce server-side cap (no pagination per tool description)
    cap = 200
    results = results[:cap]

    latency = int((time.time() - start) * 1000)
    _log("search_user_prompts", cred.get("id") if cred else None, "OK", latency, user_id=uid, meta={"query_len": len(q), "returned": len(results)})

    return {"data": {"items": results, "count": len(results), "limit": cap}}

def use_user_prompt(name, params=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        t = s.strip()
        if not t:
            return None
        try:
            if t.endswith("Z"):
                t = t[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _ulid_like(prefix):
        # deterministic-enough unique id; not a real ULID but follows prefix convention
        h = hashlib.sha1(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:22]
        return f"{prefix}_{h}"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status_s, user_id=None, credential=None, meta=None):
        logs = _ensure_logs()
        row = {
            "id": _ulid_like("aik_log"),
            "endpoint": "use_user_prompt",
            "credential": credential,
            "user_id": user_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit(user_id, limit=120, window_sec=60):
        if not user_id:
            return True, None
        logs = _ensure_logs()
        now = _now()
        cutoff = now - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != user_id:
                continue
            if r.get("endpoint") != "use_user_prompt":
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, _err("RATE_LIMIT", f"Rate limit exceeded: {limit}/{window_sec}s")
        return True, None

    def _normalize_search_text(nm, desc, tmpl):
        nm = (nm or "").strip()
        desc = (desc or "").strip()
        tmpl = (tmpl or "").strip()
        snippet = tmpl[:500]
        text = " ".join([nm, desc, snippet]).strip().lower()
        text = re.sub(r"\s+", " ", text)
        return text

    def _authenticate_ambient():
        """
        No explicit credential in tool params. Choose an active user that can serve the call.
        Heuristic: prefer most recently used active token, else any active user.
        """
        users = _load("users.json")
        users = users if isinstance(users, list) else []
        toks = _load("auth_tokens.json")
        toks = toks if isinstance(toks, list) else []

        by_id = {u.get("id"): u for u in users if isinstance(u, dict) and isinstance(u.get("id"), str)}
        now = _now()

        active_token_rows = []
        for t in toks:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            uid = t.get("user_id")
            u = by_id.get(uid)
            if not u or u.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                continue
            last = _parse_dt(t.get("last_used_at")) or _parse_dt(t.get("updated_at")) or _parse_dt(t.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            active_token_rows.append((last, t, u))

        if active_token_rows:
            active_token_rows.sort(key=lambda x: x[0], reverse=True)
            _, tok, u = active_token_rows[0]
            return u, tok

        # fallback: any active user
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str):
                return u, None
        return None, None

    # Validate inputs first
    if not isinstance(name, str) or not name.strip():
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "name"}})
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if params is None:
        params = {}
    if not isinstance(params, dict):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "params"}})
        return _err("VALIDATION_ERROR", "params must be an object (dict)", field="params")

    # Coerce/validate param values are strings
    coerced_params = {}
    for k, v in params.items():
        if not isinstance(k, str) or not k:
            _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "params"}})
            return _err("VALIDATION_ERROR", "params keys must be non-empty strings", field="params")
        if isinstance(v, str):
            coerced_params[k] = v
        elif v is None:
            # reject nulls rather than persisting ambiguous values
            _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": f"params.{k}"}})
            return _err("VALIDATION_ERROR", "params values must be strings (null not allowed)", field=f"params.{k}")
        else:
            # per rules: reject OR coerce; choose coercion to keep usability, but ensure persisted as string
            coerced_params[k] = str(v)

    # Authenticate (ambient)
    user, token_row = _authenticate_ambient()
    if not user:
        _log("error", meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "Not authenticated")
    if user.get("status") in ("suspended", "deleted"):
        _log("error", user_id=user.get("id"), meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "User is not allowed to operate (suspended/deleted)")

    ok, rate_err = _rate_limit(user.get("id"))
    if not ok:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": rate_err["error"]})
        return rate_err

    prompts = _load("prompts.json")
    prompts = prompts if isinstance(prompts, list) else []
    shares = _load("prompt_shares.json")
    shares = shares if isinstance(shares, list) else []

    # Build share maps for user
    share_by_prompt = {}
    for s in shares:
        if not isinstance(s, dict):
            continue
        if s.get("status") != "active":
            continue
        if s.get("shared_with_user_id") != user.get("id"):
            continue
        pid = s.get("prompt_id")
        perm = s.get("permission")
        if not isinstance(pid, str) or perm not in ("read", "use"):
            continue
        # keep strongest permission
        prev = share_by_prompt.get(pid)
        if prev == "use":
            continue
        share_by_prompt[pid] = perm

    # Resolve by name with preference: owned > shared > public; deterministic tie-break by id
    candidates_owned = []
    candidates_shared = []
    candidates_public = []
    target_name = name.strip()

    for p in prompts:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        if p.get("name") != target_name:
            continue
        pid = p.get("id")
        if not isinstance(pid, str):
            continue
        if p.get("owner_user_id") == user.get("id"):
            candidates_owned.append(p)
        elif pid in share_by_prompt:
            candidates_shared.append(p)
        elif p.get("visibility") == "public":
            candidates_public.append(p)

    def _pick(lst):
        lst2 = [x for x in lst if isinstance(x, dict) and isinstance(x.get("id"), str)]
        if not lst2:
            return None
        lst2.sort(key=lambda r: r.get("id"))
        return lst2[0]

    prompt = _pick(candidates_owned) or _pick(candidates_shared) or _pick(candidates_public)
    if not prompt:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND"}})
        return _err("NOT_FOUND", "Prompt not found or not accessible")

    # Permission check for use on private prompts not owned
    if prompt.get("owner_user_id") != user.get("id") and prompt.get("visibility") == "private":
        perm = share_by_prompt.get(prompt.get("id"))
        if perm != "use":
            _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "UNAUTHORIZED"}})
            return _err("UNAUTHORIZED", "Prompt is private and not shared with 'use' permission")

    # Render with schema
    schema = prompt.get("param_schema")
    if schema is not None and not isinstance(schema, dict):
        schema = None

    missing_required = []
    allowed_keys = None
    if schema:
        allowed_keys = set(schema.keys())
        for k, spec in schema.items():
            if not isinstance(k, str):
                continue
            req = False
            default = None
            if isinstance(spec, dict):
                req = bool(spec.get("required")) if "required" in spec else False
                default = spec.get("default") if "default" in spec else None
            if k not in coerced_params and default is not None:
                coerced_params[k] = str(default) if not isinstance(default, str) else default
            if req and k not in coerced_params:
                missing_required.append(k)

    # If schema exists, reject extra params not declared (business description mentions "不允许的参数导致无法渲染")
    if allowed_keys is not None:
        extras = [k for k in coerced_params.keys() if k not in allowed_keys]
        if extras:
            # log event as failed too
            events = _load("prompt_use_events.json")
            events = events if isinstance(events, list) else []
            nowiso = _iso(_now())
            events.append({
                "id": _ulid_like("aik_use"),
                "user_id": user.get("id"),
                "prompt_id": prompt.get("id"),
                "prompt_name_snapshot": prompt.get("name") or target_name,
                "params": coerced_params,
                "rendered_text": "Invalid params: " + ", ".join(extras),
                "render_status": "failed",
                "error_message": f"Unexpected params not allowed by param_schema: {', '.join(extras)}",
                "created_at": nowiso,
                "updated_at": nowiso,
            })
            _save("prompt_use_events.json", events)
            if token_row:
                token_row["last_used_at"] = nowiso
                token_row["updated_at"] = nowiso
                toks = _load("auth_tokens.json")
                toks = toks if isinstance(toks, list) else []
                changed = False
                for i, t in enumerate(toks):
                    if isinstance(t, dict) and t.get("id") == token_row.get("id"):
                        toks[i] = token_row
                        changed = True
                        break
                if changed:
                    _save("auth_tokens.json", toks)
            _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "VALIDATION_ERROR"}})
            return _err("VALIDATION_ERROR", f"Unexpected params not allowed by param_schema: {', '.join(extras)}", field="params")

    # Template rendering
    template = prompt.get("template")
    if not isinstance(template, str) or not template:
        template = ""

    render_status = "succeeded"
    error_message = None
    rendered = template

    if missing_required:
        render_status = "failed"
        error_message = f"Missing required params: {', '.join(missing_required)}"
        rendered = error_message
    else:
        # replace {{key}} placeholders
        def repl(m):
            key = m.group(1)
            return coerced_params.get(key, m.group(0))

        try:
            rendered = re.sub(r"\{\{\s*([a-zA-Z0-9_]+)\s*\}\}", repl, template)
            if not isinstance(rendered, str) or len(rendered) < 1:
                render_status = "failed"
                error_message = "Rendered text is empty"
                rendered = error_message
            elif len(rendered) > 50000:
                render_status = "failed"
                error_message = "Rendered text exceeds maximum length (50000)"
                rendered = error_message
        except re.error as e:
            render_status = "failed"
            error_message = f"Template rendering error: {str(e)}"
            rendered = error_message

    # Write use event (always)
    events = _load("prompt_use_events.json")
    events = events if isinstance(events, list) else []
    nowiso = _iso(_now())
    event_row = {
        "id": _ulid_like("aik_use"),
        "user_id": user.get("id"),
        "prompt_id": prompt.get("id"),
        "prompt_name_snapshot": prompt.get("name") or target_name,
        "params": coerced_params if coerced_params else {},
        "rendered_text": rendered if isinstance(rendered, str) and rendered else " ",
        "render_status": render_status,
        "error_message": error_message,
        "created_at": nowiso,
        "updated_at": nowiso,
    }
    if render_status == "failed" and not event_row.get("error_message"):
        event_row["error_message"] = "Rendering failed"
    events.append(event_row)
    _save("prompt_use_events.json", events)

    # Update token last_used_at (best-effort, no blanket except)
    if token_row:
        toks = _load("auth_tokens.json")
        toks = toks if isinstance(toks, list) else []
        changed = False
        for i, t in enumerate(toks):
            if isinstance(t, dict) and t.get("id") == token_row.get("id"):
                toks[i] = dict(toks[i])
                toks[i]["last_used_at"] = nowiso
                toks[i]["updated_at"] = nowiso
                changed = True
                break
        if changed:
            _save("auth_tokens.json", toks)

    if render_status == "failed":
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "VALIDATION_ERROR", "message": error_message}})
        return _err("VALIDATION_ERROR", error_message or "Rendering failed")

    _log("ok", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"prompt_id": prompt.get("id")})
    return {
        "prompt_id": prompt.get("id"),
        "name": prompt.get("name"),
        "rendered_text": rendered,
        "render_status": render_status,
        "event_id": event_row.get("id"),
        "used_at": nowiso,
    }

def get_user_prompt_info(name, **_extra):
    import json, os, datetime, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        try:
            if t.endswith("Z"):
                t = t[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(endpoint, credential, status_s, latency_ms, user_id=None, meta=None):
        logs = _ensure_request_logs()
        row = {
            "id": "aik_log_" + hashlib.sha1(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "credential": credential,
            "user_id": user_id,
            "status": status_s,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) else None,
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(user_id, endpoint, limit=300, window_sec=60):
        if not user_id:
            return True, None
        logs = _ensure_request_logs()
        now = _now()
        cutoff = now - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("user_id") != user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, {"limit": limit, "window_sec": window_sec, "retry_after_sec": 1}
        return True, None

    def _auth_ambient_user():
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active":
                return u, "ambient"
        return None, None

    def _hash_token(raw):
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _auth_from_context_if_present():
        user_token = _extra.get("user_token") if isinstance(_extra, dict) else None
        if not user_token:
            return _auth_ambient_user()
        if not isinstance(user_token, str) or not user_token.strip():
            return None, None
        tok = user_token.strip()
        users = _load("users.json")
        if not isinstance(users, list):
            users = []
        if tok.startswith("aik_usr_"):
            u = next((r for r in users if isinstance(r, dict) and r.get("id") == tok), None)
            if not u or u.get("status") != "active":
                return None, None
            return u, "user_id"
        auth_tokens = _load("auth_tokens.json")
        if not isinstance(auth_tokens, list):
            auth_tokens = []
        h = _hash_token(tok)
        now = _now()
        at = None
        for r in auth_tokens:
            if not isinstance(r, dict):
                continue
            if r.get("token_hash") != h:
                continue
            if r.get("status") != "active":
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            at = r
            break
        if not at:
            return None, None
        u = next((r for r in users if isinstance(r, dict) and r.get("id") == at.get("user_id")), None)
        if not u or u.get("status") != "active":
            return None, None
        at["last_used_at"] = _iso(now)
        at["updated_at"] = _iso(now)
        _save("auth_tokens.json", auth_tokens)
        return u, at.get("id") or "token"

    endpoint = "get_user_prompt_info"
    user, cred = _auth_from_context_if_present()
    if not user:
        _log(endpoint, cred, "error", (time.time() - t0) * 1000, user_id=None, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authenticated")

    ok_rl, rl_meta = _rate_limit_check(user.get("id"), endpoint, limit=300, window_sec=60)
    if not ok_rl:
        _log(endpoint, cred, "error", (time.time() - t0) * 1000, user_id=user.get("id"), meta={"code": "RATE_LIMIT", **(rl_meta or {})})
        return _err("RATE_LIMIT", "Too many requests", **(rl_meta or {}))

    if not isinstance(name, str) or not name.strip():
        _log(endpoint, cred, "error", (time.time() - t0) * 1000, user_id=user.get("id"), meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string")

    prompts = _load("prompts.json")
    if not isinstance(prompts, list):
        prompts = []
    shares = _load("prompt_shares.json")
    if not isinstance(shares, list):
        shares = []

    target_name = name.strip()

    # Build share map for this user
    shared_map = {}
    for sh in shares:
        if not isinstance(sh, dict):
            continue
        if sh.get("status") != "active":
            continue
        if sh.get("shared_with_user_id") != user.get("id"):
            continue
        pid = sh.get("prompt_id")
        if not pid:
            continue
        perm = sh.get("permission")
        if perm not in ("read", "use"):
            continue
        prev = shared_map.get(pid)
        if prev is None or (prev == "read" and perm == "use"):
            shared_map[pid] = perm

    cands = []
    for p in prompts:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        if p.get("name") != target_name:
            continue
        pid = p.get("id") or ""
        if p.get("owner_user_id") == user.get("id"):
            cands.append((0, pid, "owned", "use", p))
        elif pid in shared_map:
            cands.append((1, pid, "shared", shared_map.get(pid), p))
        elif p.get("visibility") == "public":
            cands.append((2, pid, "public", "use", p))
    cands.sort(key=lambda x: (x[0], x[1]))

    if not cands:
        _log(endpoint, cred, "error", (time.time() - t0) * 1000, user_id=user.get("id"), meta={"code": "NOT_FOUND", "name": target_name})
        return _err("NOT_FOUND", "Prompt not found or not accessible")

    _, _, scope, perm, prompt = cands[0]
    _log(endpoint, cred, "ok", (time.time() - t0) * 1000, user_id=user.get("id"), meta={"prompt_id": prompt.get("id"), "scope": scope, "permission": perm})
    return {
        "prompt": prompt,
        "access": {
            "scope": scope,
            "permission": perm,
            "can_use": True if (prompt.get("owner_user_id") == user.get("id") or prompt.get("visibility") == "public" or perm == "use") else False,
        },
    }

def list_user_prompts(type=None, category=None, limit=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        try:
            if t.endswith("Z"):
                t = t[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(endpoint, credential, status, latency_ms, user_id=None, meta=None):
        logs = _ensure_request_logs()
        row = {
            "id": "aik_log_" + hashlib.sha1(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "credential": credential,
            "user_id": user_id,
            "status": status,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) else None,
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(user_id, endpoint, limit=120, window_sec=60):
        if not user_id:
            return True, None
        logs = _ensure_request_logs()
        now = _now()
        cutoff = now - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("user_id") != user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, {"limit": limit, "window_sec": window_sec}
        return True, None

    def _get_ambient_credential():
        for k in ("user_token", "auth_token", "token", "authorization"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                return v.strip()
        v = os.environ.get("AIK_USER_TOKEN") or os.environ.get("USER_TOKEN") or os.environ.get("AUTH_TOKEN")
        if isinstance(v, str) and v.strip():
            return v.strip()
        uid = os.environ.get("AIK_USER_ID") or os.environ.get("USER_ID")
        if isinstance(uid, str) and uid.strip():
            return uid.strip()
        return None

    def _hash_token(raw):
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _resolve_user_and_token():
        users = _load("users.json")
        tokens = _load("auth_tokens.json")
        now = _now()
        provided = _get_ambient_credential()

        def _user_active(u):
            return isinstance(u, dict) and u.get("status") == "active"

        if isinstance(provided, str) and provided.startswith("aik_usr_"):
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == provided), None)
            if not u or not _user_active(u):
                return None, None
            return u, None

        if isinstance(provided, str) and provided.startswith("aik_tok_"):
            t = next((x for x in tokens if isinstance(x, dict) and x.get("id") == provided), None)
            if not t or t.get("status") != "active":
                return None, None
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                return None, None
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
            if not u or not _user_active(u):
                return None, None
            return u, t

        if isinstance(provided, str) and provided.strip():
            h = _hash_token(provided.strip())
            t = next((x for x in tokens if isinstance(x, dict) and x.get("token_hash") == h and x.get("status") == "active"), None)
            if t:
                exp = _parse_dt(t.get("expires_at"))
                if exp is None or exp > now:
                    u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
                    if u and _user_active(u):
                        return u, t

        # Ambient selection
        candidates = []
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                continue
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
            if not u or not _user_active(u):
                continue
            lu = _parse_dt(t.get("last_used_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            ca = _parse_dt(t.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            candidates.append((lu, ca, t, u))
        if not candidates:
            return None, None
        candidates.sort(reverse=True)
        _, _, t, u = candidates[0]
        return u, t

    start = time.time()

    # Validate inputs
    if type is None:
        type = "all"
    if not isinstance(type, str) or type not in ("all", "owned", "public"):
        return _err("VALIDATION_ERROR", "type must be one of: all, owned, public")

    # limit: schema is number; accept int/float; default 50; clamp [1,200]
    if limit is None:
        lim = 50
    elif isinstance(limit, (int, float)) and not isinstance(limit, bool):
        lim = int(limit)
    else:
        return _err("VALIDATION_ERROR", "limit must be a number")
    if lim < 1:
        return _err("VALIDATION_ERROR", "limit must be >= 1")
    if lim > 200:
        lim = 200

    # category optional string
    cat_norm = None
    if category is not None:
        if not isinstance(category, str):
            return _err("VALIDATION_ERROR", "category must be a string")
        cat_norm = re.sub(r"\s+", " ", category.strip()).lower()

    user, token = _resolve_user_and_token()
    if not user:
        latency = int((time.time() - start) * 1000)
        _log("list_user_prompts", None, "UNAUTHORIZED", latency, user_id=None, meta={"type": type})
        return _err("UNAUTHORIZED", "Not authenticated")

    uid = user.get("id")
    ok, info = _rate_limit_check(uid, "list_user_prompts", limit=120, window_sec=60)
    if not ok:
        latency = int((time.time() - start) * 1000)
        _log("list_user_prompts", token.get("id") if token else None, "RATE_LIMIT", latency, user_id=uid, meta=info)
        return _err("RATE_LIMIT", "Too many requests", **(info or {}))

    prompts = _load("prompts.json")
    shares = _load("prompt_shares.json")

    shared_ids = set()
    if type in ("all",):
        for s in shares:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "active":
                continue
            if s.get("shared_with_user_id") != uid:
                continue
            pid = s.get("prompt_id")
            if isinstance(pid, str) and pid:
                shared_ids.add(pid)

    items = []
    for p in prompts:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue

        if type == "owned":
            if p.get("owner_user_id") != uid:
                continue
        elif type == "public":
            if p.get("visibility") != "public":
                continue
        else:  # all
            pid = p.get("id")
            if not (p.get("owner_user_id") == uid or p.get("visibility") == "public" or (isinstance(pid, str) and pid in shared_ids)):
                continue

        if cat_norm is not None:
            pc = p.get("category")
            pc_norm = re.sub(r"\s+", " ", pc.strip()).lower() if isinstance(pc, str) else ""
            if pc_norm != cat_norm:
                continue

        items.append(p)

    # Deterministic sort: updated_at desc, then created_at desc, then id asc
    def _sortkey(p):
        ua = _parse_dt(p.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        ca = _parse_dt(p.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (-int(ua.timestamp()), -int(ca.timestamp()), p.get("id") or "")

    items.sort(key=_sortkey)
    items = items[:lim]

    latency = int((time.time() - start) * 1000)
    _log("list_user_prompts", token.get("id") if token else None, "OK", latency, user_id=uid, meta={"type": type, "returned": len(items), "limit": lim})

    return {"data": {"items": items, "count": len(items), "limit": lim, "type": type, "category": category}}

def create_user_prompt(name, visibility, template, category=None, description=None, param_schema=None, **_extra):
    import json, os, datetime, hashlib, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        try:
            if t.endswith("Z"):
                t = t[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(endpoint, credential, status, latency_ms, user_id=None, meta=None):
        logs = _ensure_request_logs()
        row = {
            "id": "aik_log_" + hashlib.sha1(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "credential": credential,
            "user_id": user_id,
            "status": status,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) else None,
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(user_id, endpoint, limit=60, window_sec=60):
        if not user_id:
            return True, None
        logs = _ensure_request_logs()
        now = _now()
        cutoff = now - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("user_id") != user_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, {"limit": limit, "window_sec": window_sec}
        return True, None

    def _get_ambient_credential():
        for k in ("user_token", "auth_token", "token", "authorization"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                return v.strip()
        v = os.environ.get("AIK_USER_TOKEN") or os.environ.get("USER_TOKEN") or os.environ.get("AUTH_TOKEN")
        if isinstance(v, str) and v.strip():
            return v.strip()
        uid = os.environ.get("AIK_USER_ID") or os.environ.get("USER_ID")
        if isinstance(uid, str) and uid.strip():
            return uid.strip()
        return None

    def _hash_token(raw):
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _resolve_user_and_token():
        users = _load("users.json")
        tokens = _load("auth_tokens.json")
        now = _now()
        provided = _get_ambient_credential()

        def _user_active(u):
            return isinstance(u, dict) and u.get("status") == "active"

        if isinstance(provided, str) and provided.startswith("aik_usr_"):
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == provided), None)
            if not u or not _user_active(u):
                return None, None
            return u, None

        if isinstance(provided, str) and provided.startswith("aik_tok_"):
            t = next((x for x in tokens if isinstance(x, dict) and x.get("id") == provided), None)
            if not t or t.get("status") != "active":
                return None, None
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                return None, None
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
            if not u or not _user_active(u):
                return None, None
            return u, t

        if isinstance(provided, str) and provided.strip():
            h = _hash_token(provided.strip())
            t = next((x for x in tokens if isinstance(x, dict) and x.get("token_hash") == h and x.get("status") == "active"), None)
            if t:
                exp = _parse_dt(t.get("expires_at"))
                if exp is None or exp > now:
                    u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
                    if u and _user_active(u):
                        return u, t

        # Ambient selection
        candidates = []
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                continue
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == t.get("user_id")), None)
            if not u or not _user_active(u):
                continue
            lu = _parse_dt(t.get("last_used_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            ca = _parse_dt(t.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            candidates.append((lu, ca, t, u))
        if not candidates:
            return None, None
        candidates.sort(reverse=True)
        _, _, t, u = candidates[0]
        return u, t

    def _make_id(prefix):
        ts = int(_now().timestamp() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ts:x}{rnd:020x}"

    def _recalc_search_text(nm, desc, tpl):
        nm = nm if isinstance(nm, str) else ""
        desc = desc if isinstance(desc, str) else ""
        tpl = tpl if isinstance(tpl, str) else ""
        snippet = tpl[:2000]
        s = (nm + " " + desc + " " + snippet).strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    start = time.time()

    # Validate fields
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    nm = name.strip()
    if len(nm) < 1 or len(nm) > 120:
        return _err("VALIDATION_ERROR", "name length must be between 1 and 120")

    if visibility not in ("private", "public"):
        return _err("VALIDATION_ERROR", "visibility must be 'private' or 'public'")

    if not isinstance(template, str) or not template.strip():
        return _err("VALIDATION_ERROR", "template must be a non-empty string")
    tpl = template
    if len(tpl) < 1 or len(tpl) > 20000:
        return _err("VALIDATION_ERROR", "template length must be between 1 and 20000")

    if category is not None and not isinstance(category, str):
        return _err("VALIDATION_ERROR", "category must be a string")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string")
    if param_schema is not None and not isinstance(param_schema, dict):
        return _err("VALIDATION_ERROR", "param_schema must be an object")

    user, token = _resolve_user_and_token()
    if not user:
        latency = int((time.time() - start) * 1000)
        _log("create_user_prompt", None, "UNAUTHORIZED", latency, user_id=None, meta={"name": nm})
        return _err("UNAUTHORIZED", "Not authenticated")

    uid = user.get("id")
    ok, info = _rate_limit_check(uid, "create_user_prompt", limit=60, window_sec=60)
    if not ok:
        latency = int((time.time() - start) * 1000)
        _log("create_user_prompt", token.get("id") if token else None, "RATE_LIMIT", latency, user_id=uid, meta=info)
        return _err("RATE_LIMIT", "Too many requests", **(info or {}))

    # user status already active enforced by auth; but keep forbidden if somehow not
    if user.get("status") != "active":
        latency = int((time.time() - start) * 1000)
        _log("create_user_prompt", token.get("id") if token else None, "UNAUTHORIZED", latency, user_id=uid)
        return _err("UNAUTHORIZED", "User not active")

    prompts = _load("prompts.json")
    if not isinstance(prompts, list):
        prompts = []

    # Unique(owner_user_id, name)
    for p in prompts:
        if not isinstance(p, dict):
            continue
        if p.get("owner_user_id") == uid and p.get("name") == nm and p.get("status") != "deleted":
            latency = int((time.time() - start) * 1000)
            _log("create_user_prompt", token.get("id") if token else None, "CONFLICT", latency, user_id=uid, meta={"name": nm})
            return _err("CONFLICT", "Prompt name already exists for this user")

    now_iso = _iso(_now())
    row = {
        "id": _make_id("aik_prm_"),
        "owner_user_id": uid,
        "name": nm,
        "visibility": visibility,
        "category": category,
        "description": description,
        "template": tpl,
        "param_schema": param_schema,
        "search_text": _recalc_search_text(nm, description, tpl),
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    prompts.append(row)
    _save("prompts.json", prompts)

    latency = int((time.time() - start) * 1000)
    _log("create_user_prompt", token.get("id") if token else None, "OK", latency, user_id=uid, meta={"prompt_id": row["id"]})

    return {"data": {"prompt": row}}

def update_user_prompt(prompt_id, name=None, visibility=None, category=None, description=None, template=None, param_schema=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        t = s.strip()
        if not t:
            return None
        try:
            if t.endswith("Z"):
                t = t[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _ulid_like(prefix):
        h = hashlib.sha1(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:22]
        return f"{prefix}_{h}"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status_s, user_id=None, credential=None, meta=None):
        logs = _ensure_logs()
        row = {
            "id": _ulid_like("aik_log"),
            "endpoint": "update_user_prompt",
            "credential": credential,
            "user_id": user_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit(user_id, limit=60, window_sec=60):
        if not user_id:
            return True, None
        logs = _ensure_logs()
        now = _now()
        cutoff = now - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != user_id:
                continue
            if r.get("endpoint") != "update_user_prompt":
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, _err("RATE_LIMIT", f"Rate limit exceeded: {limit}/{window_sec}s")
        return True, None

    def _normalize_search_text(nm, desc, tmpl):
        nm = (nm or "").strip()
        desc = (desc or "").strip()
        tmpl = (tmpl or "").strip()
        snippet = tmpl[:500]
        text = " ".join([nm, desc, snippet]).strip().lower()
        text = re.sub(r"\s+", " ", text)
        return text

    def _authenticate_ambient():
        users = _load("users.json")
        users = users if isinstance(users, list) else []
        toks = _load("auth_tokens.json")
        toks = toks if isinstance(toks, list) else []

        by_id = {u.get("id"): u for u in users if isinstance(u, dict) and isinstance(u.get("id"), str)}
        now = _now()
        active_token_rows = []
        for t in toks:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            uid = t.get("user_id")
            u = by_id.get(uid)
            if not u or u.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                continue
            last = _parse_dt(t.get("last_used_at")) or _parse_dt(t.get("updated_at")) or _parse_dt(t.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            active_token_rows.append((last, t, u))
        if active_token_rows:
            active_token_rows.sort(key=lambda x: x[0], reverse=True)
            _, tok, u = active_token_rows[0]
            return u, tok
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str):
                return u, None
        return None, None

    # Validate inputs
    if not isinstance(prompt_id, str) or not prompt_id.strip():
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "prompt_id"}})
        return _err("VALIDATION_ERROR", "prompt_id must be a non-empty string", field="prompt_id")

    if visibility is not None and visibility not in ("private", "public"):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "visibility"}})
        return _err("VALIDATION_ERROR", "visibility must be 'private' or 'public'", field="visibility")

    if name is not None:
        if not isinstance(name, str) or not name.strip():
            _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "name"}})
            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        if not (1 <= len(name.strip()) <= 120):
            _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "name"}})
            return _err("VALIDATION_ERROR", "name length must be between 1 and 120", field="name")

    if template is not None:
        if not isinstance(template, str) or not template.strip():
            _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "template"}})
            return _err("VALIDATION_ERROR", "template must be a non-empty string", field="template")
        if not (1 <= len(template) <= 20000):
            _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "template"}})
            return _err("VALIDATION_ERROR", "template length must be between 1 and 20000", field="template")

    if category is not None and not isinstance(category, str):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "category"}})
        return _err("VALIDATION_ERROR", "category must be a string", field="category")

    if description is not None and not isinstance(description, str):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "description"}})
        return _err("VALIDATION_ERROR", "description must be a string", field="description")

    if param_schema is not None and not isinstance(param_schema, dict):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "param_schema"}})
        return _err("VALIDATION_ERROR", "param_schema must be an object", field="param_schema")

    # Auth
    user, token_row = _authenticate_ambient()
    if not user:
        _log("error", meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "Not authenticated")
    if user.get("status") in ("suspended", "deleted"):
        _log("error", user_id=user.get("id"), meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "User is not allowed to operate (suspended/deleted)")

    ok, rate_err = _rate_limit(user.get("id"))
    if not ok:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": rate_err["error"]})
        return rate_err

    prompts = _load("prompts.json")
    prompts = prompts if isinstance(prompts, list) else []

    idx = None
    prompt = None
    for i, p in enumerate(prompts):
        if isinstance(p, dict) and p.get("id") == prompt_id:
            idx = i
            prompt = p
            break
    if not prompt:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND"}})
        return _err("NOT_FOUND", "Prompt not found")

    # Only owner can update
    if prompt.get("owner_user_id") != user.get("id"):
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND"}})
        return _err("NOT_FOUND", "Prompt not found or not manageable (only owner can update)")

    # Status restriction
    if prompt.get("status") == "deleted":
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "INVALID_TRANSITION"}})
        return _err("INVALID_TRANSITION", "Prompt is deleted and cannot be modified (business rule: deleted immutable)")

    # Determine changes (must have effect)
    updated = dict(prompt)
    changed = False

    if name is not None:
        new_name = name.strip()
        if new_name != updated.get("name"):
            # unique(owner_user_id, name)
            for p in prompts:
                if not isinstance(p, dict):
                    continue
                if p.get("id") == prompt_id:
                    continue
                if p.get("owner_user_id") == user.get("id") and p.get("name") == new_name:
                    _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "CONFLICT"}})
                    return _err("CONFLICT", "A prompt with the same name already exists for this user", field="name")
            updated["name"] = new_name
            changed = True

    if visibility is not None and visibility != updated.get("visibility"):
        updated["visibility"] = visibility
        changed = True

    if category is not None and category != updated.get("category"):
        updated["category"] = category
        changed = True

    if description is not None and description != updated.get("description"):
        updated["description"] = description
        changed = True

    if template is not None and template != updated.get("template"):
        updated["template"] = template
        changed = True

    if param_schema is not None and param_schema != updated.get("param_schema"):
        updated["param_schema"] = param_schema
        changed = True

    if not changed:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND", "message": "No changes"}})
        return _err("NOT_FOUND", "No fields were changed; nothing to update")

    # Maintain search_text if name/description/template changed or if it is missing
    updated["search_text"] = _normalize_search_text(updated.get("name"), updated.get("description"), updated.get("template"))
    nowiso = _iso(_now())
    updated["updated_at"] = nowiso

    prompts[idx] = updated
    _save("prompts.json", prompts)

    # Update token last_used_at
    if token_row:
        toks = _load("auth_tokens.json")
        toks = toks if isinstance(toks, list) else []
        for i, t in enumerate(toks):
            if isinstance(t, dict) and t.get("id") == token_row.get("id"):
                toks[i] = dict(toks[i])
                toks[i]["last_used_at"] = nowiso
                toks[i]["updated_at"] = nowiso
                _save("auth_tokens.json", toks)
                break

    _log("ok", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"prompt_id": prompt_id})
    return {"prompt": updated}

