            if not u or u.get("status") != "active":
                continue
            last = _parse_dt(t.get("last_used_at")) or _parse_dt(t.get("updated_at")) or _parse_dt(t.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if best is None or last > best[0]:
                best = (last, u, t)
        if best:
            return best[1], best[2]
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str):
                return u, None
        return None, None

    # Validate
    if not isinstance(prompt_id, str) or not prompt_id.strip():
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "prompt_id"}})
        return _err("VALIDATION_ERROR", "prompt_id must be a non-empty string", field="prompt_id")
    if status not in ("active", "archived", "deleted"):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "status"}})
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")

    user, token_row = _authenticate_ambient()
    if not user:
        _log("error", meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "Not authenticated")
    if user.get("status") in ("suspended", "deleted"):
        _log("error", user_id=user.get("id"), meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "User is not allowed to operate (suspended/deleted)")

    ok, rate_err = _rate_limit(user.get("id"))
    if not ok:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": rate_err["error"]})
        return rate_err

    prompts = _load("prompts.json")
    prompts = prompts if isinstance(prompts, list) else []

    idx = None
    prompt = None
    for i, p in enumerate(prompts):
        if isinstance(p, dict) and p.get("id") == prompt_id:
            idx = i
            prompt = p
            break
    if not prompt:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND"}})
        return _err("NOT_FOUND", "Prompt not found")

    if prompt.get("owner_user_id") != user.get("id"):
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND"}})
        return _err("NOT_FOUND", "Prompt not found or not manageable (only owner can change status)")

    current = prompt.get("status")
    transitions = {
        "active": set(["archived", "deleted"]),
        "archived": set(["active", "deleted"]),
        "deleted": set([]),
    }
    if current not in transitions:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "VALIDATION_ERROR"}})
        return _err("VALIDATION_ERROR", "Current prompt status is invalid", field="status")

    if status == current:
        _log("ok", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"prompt_id": prompt_id, "idempotent": True})
        return {"prompt_id": prompt_id, "status": current}

    if status not in transitions[current]:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "INVALID_TRANSITION"}})
        return _err("INVALID_TRANSITION", f"Illegal status transition: {current} -> {status}", from_status=current, to_status=status)

    updated = dict(prompt)
    updated["status"] = status
    nowiso = _iso(_now())
    updated["updated_at"] = nowiso
    prompts[idx] = updated
    _save("prompts.json", prompts)

    if token_row:
        toks = _load("auth_tokens.json")
        toks = toks if isinstance(toks, list) else []
        for i, t in enumerate(toks):
            if isinstance(t, dict) and t.get("id") == token_row.get("id"):
                toks[i] = dict(toks[i])
                toks[i]["last_used_at"] = nowiso
                toks[i]["updated_at"] = nowiso
                _save("auth_tokens.json", toks)
                break

    _log("ok", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"prompt_id": prompt_id, "from": current, "to": status})
    return {"prompt_id": prompt_id, "status": status}

def list_prompt_use_events(prompt_id=None, render_status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            # not expected in schema
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid():
        # time-sortable, ULID-like (not strictly spec), prefixless
        # 48-bit time (ms) + 80-bit randomness => 26 chars base32 crockford
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        value = (ts << 80) | rnd
        out = []
        for _ in range(26):
            out.append(alphabet[value & 31])
            value >>= 5
        return "".join(reversed(out))

    def _hash_token(raw):
        # token_hash stored; business rule says hash raw token then match
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _get_current_user():
        # Ambient auth: find any active, non-suspended/non-deleted user that has an active, unexpired token.
        users = _load("users.json")
        tokens = _load("auth_tokens.json")
        now_dt = datetime.datetime.utcnow()
        # Prefer tokens with most recent use for determinism (if present), then created_at.
        def tok_sort_key(t):
            lu = _parse_dt(t.get("last_used_at")) or datetime.datetime.min
            ca = _parse_dt(t.get("created_at")) or datetime.datetime.min
            return (lu, ca)
        valid = []
        for t in tokens:
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now_dt):
                continue
            uid = t.get("user_id")
            if not isinstance(uid, str):
                continue
            u = next((x for x in users if x.get("id") == uid), None)
            if not u:
                continue
            if u.get("status") != "active":
                continue
            valid.append((t, u))
        if not valid:
            return None, None
        valid.sort(key=lambda tu: tok_sort_key(tu[0]), reverse=True)
        return valid[0][1], valid[0][0]

    def _ensure_request_log():
        # best-effort: if no collection exists, create one
        # filename chosen to be stable; not declared but needed for dynamics/quota.
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            _save(fname, [])
        return fname

    def _record_call(endpoint, credential_id, status, started_at, extra=None):
        fname = _ensure_request_log()
        logs = _load(fname)
        ended = time.time()
        latency_ms = int(round((ended - started_at) * 1000))
        row = {
            "id": "aik_req_" + _ulid(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now(),
        }
        if extra and isinstance(extra, dict):
            row.update({"meta": extra})
        logs.append(row)
        _save(fname, logs)

    def _enforce_rate_limit(credential_id):
        # Simple per-credential rate limit: 120 req/min; per-day quota: 10000 req/day
        fname = _ensure_request_log()
        logs = _load(fname)
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        per_min = 0
        per_day = 0
        for r in logs:
            if r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts >= day_start:
                per_day += 1
            if ts >= window_start:
                per_min += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Too many requests")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    started = time.time()

    # Validate inputs
    if prompt_id is not None and not isinstance(prompt_id, str):
        return _err("VALIDATION_ERROR", "prompt_id must be a string")
    if render_status is not None:
        if not isinstance(render_status, str):
            return _err("VALIDATION_ERROR", "render_status must be a string")
        if render_status not in ("succeeded", "failed"):
            return _err("VALIDATION_ERROR", "render_status must be one of: succeeded, failed")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    user, token_row = _get_current_user()
    if not user or not token_row:
        # no credential combination can serve
        _record_call("list_prompt_use_events", None, "UNAUTHORIZED", started_at=started)
        return _err("UNAUTHORIZED", "Authentication required")

    # Enforce rate/quota
    rl = _enforce_rate_limit(token_row.get("id"))
    if rl:
        _record_call("list_prompt_use_events", token_row.get("id"), rl["error"]["code"], started_at=started)
        return rl

    # Decode cursor
    cursor_obj = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            cursor_obj = json.loads(raw.decode("utf-8"))
        except Exception:
            _record_call("list_prompt_use_events", token_row.get("id"), "VALIDATION_ERROR", started_at=started)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(cursor_obj, dict):
            _record_call("list_prompt_use_events", token_row.get("id"), "VALIDATION_ERROR", started_at=started)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if cursor_obj.get("v") != 1:
            _record_call("list_prompt_use_events", token_row.get("id"), "VALIDATION_ERROR", started_at=started)
            return _err("VALIDATION_ERROR", "Unsupported cursor version")

    events = _load("prompt_use_events.json")
    uid = user.get("id")

    filtered = []
    for e in events:
        if e.get("user_id") != uid:
            continue
        if prompt_id is not None and e.get("prompt_id") != prompt_id:
            continue
        if render_status is not None and e.get("render_status") != render_status:
            continue
        # Only return well-formed rows; tolerate bad historical data by skipping if missing required fields
        if not isinstance(e.get("id"), str):
            continue
        filtered.append(e)

    # Sort by created_at desc then id desc for deterministic order
    def sort_key(e):
        dt = _parse_dt(e.get("created_at")) or datetime.datetime.min
        return (dt, e.get("id"))
    filtered.sort(key=sort_key, reverse=True)

    # Apply cursor: we use (created_at, id) as boundary; return items strictly older than cursor
    if cursor_obj:
        c_dt = _parse_dt(cursor_obj.get("created_at"))
        c_id = cursor_obj.get("id")
        if not c_dt or not isinstance(c_id, str):
            _record_call("list_prompt_use_events", token_row.get("id"), "VALIDATION_ERROR", started_at=started)
            return _err("VALIDATION_ERROR", "Invalid cursor payload")
        new_filtered = []
        for e in filtered:
            e_dt = _parse_dt(e.get("created_at")) or datetime.datetime.min
            e_id = e.get("id")
            if (e_dt, e_id) < (c_dt, c_id):
                new_filtered.append(e)
        filtered = new_filtered

    total = len(filtered)
    page = filtered[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"v": 1, "created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    # Update token last_used_at (observable dynamics)
    tokens = _load("auth_tokens.json")
    changed = False
    for t in tokens:
        if t.get("id") == token_row.get("id"):
            t["last_used_at"] = _now()
            t["updated_at"] = _now()
            changed = True
            break
    if changed:
        _save("auth_tokens.json", tokens)

    _record_call("list_prompt_use_events", token_row.get("id"), "OK", started_at=started, extra={"returned": len(page)})

    return {
        "data": page,
        "meta": {
            "limit": limit,
            "total_matched": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def create_prompt_share(prompt_id, shared_with_user_id, permission, status=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0480000" if __import__("os").path.isdir("./environment_mix/0480000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        t = s.strip()
        if not t:
            return None
        try:
            if t.endswith("Z"):
                t = t[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _ulid_like(prefix):
        h = hashlib.sha1(f"{time.time_ns()}".encode("utf-8")).hexdigest()[:22]
        return f"{prefix}_{h}"

    def _ensure_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(status_s, user_id=None, credential=None, meta=None):
        logs = _ensure_logs()
        row = {
            "id": _ulid_like("aik_log"),
            "endpoint": "create_prompt_share",
            "credential": credential,
            "user_id": user_id,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(_now()),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit(user_id, limit=60, window_sec=60):
        if not user_id:
            return True, None
        logs = _ensure_logs()
        now = _now()
        cutoff = now - datetime.timedelta(seconds=window_sec)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("user_id") != user_id:
                continue
            if r.get("endpoint") != "create_prompt_share":
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return False, _err("RATE_LIMIT", f"Rate limit exceeded: {limit}/{window_sec}s")
        return True, None

    def _authenticate_ambient():
        users = _load("users.json")
        users = users if isinstance(users, list) else []
        toks = _load("auth_tokens.json")
        toks = toks if isinstance(toks, list) else []
        by_id = {u.get("id"): u for u in users if isinstance(u, dict) and isinstance(u.get("id"), str)}
        now = _now()
        best = None
        for t in toks:
            if not isinstance(t, dict) or t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at"))
            if exp is not None and not (exp > now):
                continue
            u = by_id.get(t.get("user_id"))
            if not u or u.get("status") != "active":
                continue
            last = _parse_dt(t.get("last_used_at")) or _parse_dt(t.get("updated_at")) or _parse_dt(t.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if best is None or last > best[0]:
                best = (last, u, t)
        if best:
            return best[1], best[2]
        for u in users:
            if isinstance(u, dict) and u.get("status") == "active" and isinstance(u.get("id"), str):
                return u, None
        return None, None

    # Validate
    if not isinstance(prompt_id, str) or not prompt_id.strip():
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "prompt_id"}})
        return _err("VALIDATION_ERROR", "prompt_id must be a non-empty string", field="prompt_id")
    if not isinstance(shared_with_user_id, str) or not shared_with_user_id.strip():
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "shared_with_user_id"}})
        return _err("VALIDATION_ERROR", "shared_with_user_id must be a non-empty string", field="shared_with_user_id")
    if permission not in ("read", "use"):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "permission"}})
        return _err("VALIDATION_ERROR", "permission must be 'read' or 'use'", field="permission")
    if status is None:
        status = "active"
    if status not in ("active", "revoked"):
        _log("error", meta={"error": {"code": "VALIDATION_ERROR", "field": "status"}})
        return _err("VALIDATION_ERROR", "status must be 'active' or 'revoked'", field="status")

    # Auth
    user, token_row = _authenticate_ambient()
    if not user:
        _log("error", meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "Not authenticated")
    if user.get("status") in ("suspended", "deleted"):
        _log("error", user_id=user.get("id"), meta={"error": {"code": "UNAUTHORIZED"}})
        return _err("UNAUTHORIZED", "User is not allowed to operate (suspended/deleted)")

    ok, rate_err = _rate_limit(user.get("id"))
    if not ok:
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": rate_err["error"]})
        return rate_err

    users = _load("users.json")
    users = users if isinstance(users, list) else []
    if not any(isinstance(u, dict) and u.get("id") == shared_with_user_id for u in users):
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "VALIDATION_ERROR"}})
        return _err("VALIDATION_ERROR", "shared_with_user_id does not reference an existing user", field="shared_with_user_id")

    prompts = _load("prompts.json")
    prompts = prompts if isinstance(prompts, list) else []
    prompt = None
    for p in prompts:
        if isinstance(p, dict) and p.get("id") == prompt_id:
            prompt = p
            break
    if not prompt or prompt.get("owner_user_id") != user.get("id"):
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND"}})
        return _err("NOT_FOUND", "Prompt not found or not owned by current user")

    # Enforce policy: only share private prompts (as per description)
    if prompt.get("visibility") != "private":
        _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "CONFLICT"}})
        return _err("CONFLICT", "Only private prompts can be shared via prompt_shares (business rule)")

    shares = _load("prompt_shares.json")
    shares = shares if isinstance(shares, list) else []

    # Upsert by unique(prompt_id, shared_with_user_id)
    existing_idx = None
    existing = None
    for i, s in enumerate(shares):
        if not isinstance(s, dict):
            continue
        if s.get("prompt_id") == prompt_id and s.get("shared_with_user_id") == shared_with_user_id:
            existing_idx = i
            existing = s
            break

    nowiso = _iso(_now())
    if existing:
        # lifecycle: active -> revoked only; revoked cannot transition back
        cur = existing.get("status")
        if cur not in ("active", "revoked"):
            _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "VALIDATION_ERROR"}})
            return _err("VALIDATION_ERROR", "Existing share has invalid status")
        if status != cur:
            if cur == "revoked" and status == "active":
                _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "INVALID_TRANSITION"}})
                return _err("INVALID_TRANSITION", "Cannot transition share from revoked to active", from_status="revoked", to_status="active")
            if cur == "active" and status == "revoked":
                pass

        updated = dict(existing)
        changed = False
        if permission != updated.get("permission"):
            updated["permission"] = permission
            changed = True
        if status != updated.get("status"):
            updated["status"] = status
            changed = True
        if not changed:
            _log("error", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"error": {"code": "NOT_FOUND"}})
            return _err("NOT_FOUND", "No changes were made; nothing to update")
        updated["updated_at"] = nowiso
        shares[existing_idx] = updated
        _save("prompt_shares.json", shares)

        if token_row:
            toks = _load("auth_tokens.json")
            toks = toks if isinstance(toks, list) else []
            for i, t in enumerate(toks):
                if isinstance(t, dict) and t.get("id") == token_row.get("id"):
                    toks[i] = dict(toks[i])
                    toks[i]["last_used_at"] = nowiso
                    toks[i]["updated_at"] = nowiso
                    _save("auth_tokens.json", toks)
                    break

        _log("ok", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"share_id": updated.get("id")})
        return {"share": updated}

    # Create new
    row = {
        "id": _ulid_like("aik_shr"),
        "prompt_id": prompt_id,
        "shared_with_user_id": shared_with_user_id,
        "permission": permission,
        "status": status,
        "created_at": nowiso,
        "updated_at": nowiso,
    }
    shares.append(row)
    _save("prompt_shares.json", shares)

    if token_row:
        toks = _load("auth_tokens.json")
        toks = toks if isinstance(toks, list) else []
        for i, t in enumerate(toks):
            if isinstance(t, dict) and t.get("id") == token_row.get("id"):
                toks[i] = dict(toks[i])
                toks[i]["last_used_at"] = nowiso
                toks[i]["updated_at"] = nowiso
                _save("auth_tokens.json", toks)
                break

    _log("ok", user_id=user.get("id"), credential=(token_row.get("id") if token_row else None), meta={"share_id": row.get("id")})
    return {"share": row}
